static String grade(int score) {
    int bucket = Math.min(score / 10, 10);
    return switch (bucket) {
        case 10, 9 -> "A";
        case 8, 7 -> "B";
        case 6 -> "C";
        default -> "D";
    };
}
System.out.println(grade(95));
System.out.println(grade(80));
System.out.println(grade(65));
System.out.println(grade(30));

