static void buggy(int x) {
    switch (x) {
        case 1:
            System.out.println("jeden");
            // BRAK break!
        case 2:
            System.out.println("dwa");
            break;
        case 3:
            System.out.println("trzy");
            break;
    }
}
buggy(1);
// Nieoczekiwany wynik: wypisuje sie ZARÓWNO "jeden" JAK I "dwa", mimo ze x=1 - wykonanie
// spadlo (fall-through) do case 2, bo brakowalo break po case 1.

static void fixed(int x) {
    switch (x) {
        case 1 -> System.out.println("jeden");
        case 2 -> System.out.println("dwa");
        case 3 -> System.out.println("trzy");
    }
}
fixed(1);
// Teraz wypisuje sie TYLKO "jeden" - arrow switch nie ma mechanizmu fall-through,
// blad zniknal calkowicie, nie tylko zostal 'naprawiony' przez dodanie break.

static String dayCategory(int dayNumber) {
    return switch (dayNumber) {
        case 1, 2, 3, 4, 5 -> "Robocze";
        case 6, 7 -> "Weekend";
        default -> "nieprawidlowy dzien";
