}
System.out.println(dayCategory(3));
System.out.println(dayCategory(7));

static int discountFor(int quantity) {
    int bucket = quantity >= 10 ? 1 : 0;
    return switch (bucket) {
        case 1 -> {
            int base = 10;
            if (quantity > 20) {
                base += 5;
            }
            yield base;
        }
        default -> 0;
    };
}
System.out.println(discountFor(5));
System.out.println(discountFor(15));
System.out.println(discountFor(25));

