enum Direction { NORTH, SOUTH, EAST, WEST }

// (a) switch STATEMENT - kompiluje sie mimo pominietych SOUTH/WEST:
static void printDirectionA(Direction d) {
    switch (d) {
        case NORTH -> System.out.println("Polnoc");
        case EAST -> System.out.println("Wschod");
        // SOUTH i WEST pominiete - i tak sie kompiluje, po prostu cisza dla nich
    }
}

// (b) switch EXPRESSION - W KOMENTARZU, bo NIE skompiluje sie:
// static String printDirectionB(Direction d) {
//     return switch (d) {
//         case NORTH -> "Polnoc";
//         case EAST -> "Wschod";
//         // BLAD: the switch expression does not cover all possible input values
//     };
// }
// Roznica: switch STATEMENT nic nie zwraca, wiec kompilator nie wymaga wyczerpania -
// pominiete przypadki po prostu nic nie robia. switch EXPRESSION musi zwrocic wartosc
// dla KAZDEGO mozliwego wejscia, wiec brak galezi to blad kompilacji.

static String process(String category, int priority) {
    return switch (category) {
        case "A" -> {
            String inner = switch (priority) {
                case 1 -> "wysoki";
                case 2 -> "sredni";
                default -> "niski";
            };
            yield "Kategoria A, priorytet: " + inner;
        }
        case "B" -> "Kategoria B";
        default -> "Inna kategoria";
    };
}
System.out.println(process("A", 1));

static String halfOfYear(Season s) {
    return switch (s) {
        case SPRING, SUMMER -> "Cieplaa polowa roku";
        case AUTUMN, WINTER -> "Zimna polowa roku";
        default -> "Nieznana pora roku";
    };
}
// default tutaj jest ZBEDNY (4 stale sa juz w pelni pokryte), ale bywa dobra praktyka
// defensywna - UWAGA: to jest kompromis! Dodanie default OSLABIA gwarancje kompilatora -
// jesli ktos doda nowa stale do Season, switch NIE zglosi juz bledu kompilacji, tylko
// cicho przejdzie do default. Trzeba swiadomie wybrac miedzy bezpieczenstwem (bez default)
// a odpornoscia na przyszle zmiany (z default).

// if/else-if:
static String classifyOld(int code) {
    if (code >= 200 && code < 300) return "2xx";
    else if (code >= 300 && code < 400) return "3xx";
    else if (code >= 400 && code < 500) return "4xx";
    else if (code >= 500 && code < 600) return "5xx";
    else return "inny";
}

// switch-wyrazenie:
static String classifyNew(int code) {
    return switch (code / 100) {
        case 2 -> "2xx";
        case 3 -> "3xx";
        case 4 -> "4xx";
        case 5 -> "5xx";
        default -> "inny";
    };
}

static String processCode(int code) {
    if (code == -1) {
        return "BLAD KRYTYCZNY";
    }
    return switch (code) {
        case 0 -> {
            yield "zero";
        }
        default -> {
            yield "inna wartosc: " + code;
        }
    };
}
System.out.println(processCode(-1));
System.out.println(processCode(5));
// return konczy CALA metode natychmiast (jak widac na poczatku processCode); yield konczy
// TYLKO blok switch-wyrazenia, przekazujac wartosc DO switcha, ktory dopiero potem jest
// zwracany przez zewnetrzny return.

static Season parseSeason(String name) {
    return switch (name) {
        case "wiosna" -> Season.SPRING;
        case "lato" -> Season.SUMMER;
        case "jesien" -> Season.AUTUMN;
        case "zima" -> Season.WINTER;
        default -> throw new IllegalArgumentException("Nieznana pora roku: " + name);
    };
}
System.out.println(parseSeason("lato"));

static String recommend(int age) {
    String category = switch (age / 18) {
        case 0 -> "dziecko";
        case 1, 2, 3 -> "dorosly";
        default -> "senior";
    };
    return switch (category) {
        case "dziecko" -> "zabawka";
        case "dorosly" -> "laptop";
        default -> "okulary";
    };
}
System.out.println(recommend(10));
System.out.println(recommend(30));
System.out.println(recommend(70));

static String describe(int weight) {
    String parity = (weight % 2 == 0) ? "parzysta" : "nieparzysta";
    String category = switch (weight / 50) {
        case 0 -> "lekki";
        case 1 -> "sredni";
        default -> "ciezki";
    };
    return "Waga " + weight + " (" + parity + "): " + category;
}
System.out.println(describe(30));
System.out.println(describe(120));
// Ternar sprawdza sie dla PROSTYCH wyborow dwuwartosciowych - jest zwiezly i czytelny.
// Switch lepiej sprawdza sie od 3 wariantow wzwyz - ternar zagniezdzony (a ? b : c ? d : e)
// szybko staje sie nieczytelny, podczas gdy switch skaluje sie ladnie do wielu galezi.

// Klasyczny switch z ZAMIERZONYM fall-through (grupowanie):
static void classicGrouping(int x) {
    switch (x) {
        case 1:
        case 2:
        case 3:
            System.out.println("Niska wartosc");
            break;
        default:
            System.out.println("Inna wartosc");
    }
}

// Rownowazny arrow-switch:
static void arrowGrouping(int x) {
    switch (x) {
        case 1, 2, 3 -> System.out.println("Niska wartosc");
        default -> System.out.println("Inna wartosc");
    }
}
// Arrow-switch jest JEDNOZNACZNIE czytelniejszy - grupowanie 'case 1, 2, 3 ->' jest
// intencjonalne i widoczne od razu, podczas gdy klasyczny styl 'puste' case-y bez
// kodu wymaga domyslu, ze to CELOWE grupowanie, a nie zapomniany break.

enum Status { NEW, IN_PROGRESS, DONE }

static String label(Status s) {
    return switch (s) {
        case NEW -> "Nowe";
        case IN_PROGRESS -> "W trakcie";
        case DONE -> "Zakonczone";
    };
}
// Gdyby dodano czwarta stala CANCELLED do enuma Status, KAZDY exhaustive switch-wyrazenie
// (bez default) w CALYM projekcie, ktory operuje na Status, PRZESTALBY SIE KOMPILOWAC -
// kompilator wskazalby DOKLADNIE kazde miejsce wymagajace aktualizacji. To DOKLADNIE ta
// sama korzysc co przy sealed typach (Lekcja 19/21): system typow dziala jak automatyczna
// lista TODO dla refaktoryzacji, gwarantujaca ze zaden przypadek nie zostanie przeoczony.

static int process(int n) {
    int bucket = n > 100 ? 1 : 0;
    return switch (bucket) {
        case 1 -> {
            int sum = 0;
            int temp = n;
            while (temp > 0) {
                sum += temp % 10;
                temp /= 10;
            }
            yield sum;
        }
        default -> n;
    };
}
System.out.println(process(12345)); // 1+2+3+4+5 = 15
System.out.println(process(7)); // 7

// (a) jako STATEMENT:
static void printDayA(int day) {
    switch (day) {
        case 1 -> System.out.println("Poniedzialek");
        case 2 -> System.out.println("Wtorek");
        default -> System.out.println("Inny");
    }
}

// (b) jako EXPRESSION:
static void printDayB(int day) {
    String name = switch (day) {
        case 1 -> "Poniedzialek";
        case 2 -> "Wtorek";
        default -> "Inny";
    };
    System.out.println(name);
}
// STATEMENT sprawdza sie, gdy KAZDA galaz robi cos ROZNEGO (efekt uboczny) i nie ma
// wspolnej wartosci do dalszego przetworzenia. EXPRESSION sprawdza sie, gdy chcemy jedna
// WARTOSC wykorzystac DALEJ (np. przekazac do innej metody, zwrocic, polaczyc w String).

static String classifyChar(char c) {
    char lower = Character.toLowerCase(c);
    return switch (lower) {
        case 'a', 'e', 'i', 'o', 'u', 'y' -> "samogloska";
        default -> Character.isDigit(c) ? "cyfra" : Character.isLetter(c) ? "spolgloska" : "inny znak";
    };
}
for (char c : "Kot123!".toCharArray()) {
    System.out.println(c + ": " + classifyChar(c));
}

enum Action { START, STOP, PAUSE }

static Action parseCommand(String cmd) {
    return switch (cmd) {
        case "start", "run", "go" -> Action.START;
        case "stop", "halt" -> Action.STOP;
        case "pause", "wait" -> Action.PAUSE;
        default -> throw new IllegalArgumentException("Nieznana komenda: " + cmd);
    };
}
System.out.println(parseCommand("go"));
System.out.println(parseCommand("halt"));

static String mixedForm(int x) {
    return switch (x) {
        case 1 -> "jeden";
        case 2 -> {
            String s = "dwa";
            yield s.toUpperCase();
        }
        default -> "inne";
    };
}
System.out.println(mixedForm(1));
System.out.println(mixedForm(2));
System.out.println(mixedForm(5));

static String timeOfDay(int hour) {
    int bucket = hour / 6;
    return switch (bucket) {
        case 0 -> "noc";
        case 1 -> "poranek";
        case 2 -> "popoludnie";
        default -> "wieczor";
    };
}
System.out.println(timeOfDay(3));
System.out.println(timeOfDay(9));
System.out.println(timeOfDay(15));
System.out.println(timeOfDay(21));

static double compute(int mode) {
    double wynik = switch (mode) {
        case 1 -> 5; // int, automatycznie rozszerzony do double
        case 2 -> 2.5; // double
        default -> 0;
    };
    return wynik;
}
System.out.println(compute(1)); // 5.0
System.out.println(compute(2)); // 2.5
// Kompilator ANALIZUJE typy wszystkich galezi switch-wyrazenia i ujednolica CALE wyrazenie
// do NAJSZERSZEGO wspolnego typu (tu: double) - literal int '5' jest niejawnie rozszerzany
// (widening) do double, zeby typ zwracany przez switch byl SPOJNY w kazdej galezi.

// LEGACY:
static String legacy(int code) {
    String result;
    switch (code) {
        case 1:
            result = "jeden";
            break;
        case 2:
            result = "dwa";
            break;
        case 3:
            result = "trzy";
            break;
        default:
            result = "inny";
    }
    return result;
}

// ZREFAKTORYZOWANE:
static String modern(int code) {
    return switch (code) {
        case 1 -> "jeden";
        case 2 -> "dwa";
        case 3 -> "trzy";
        default -> "inny";
    };
}
// Refaktoryzacja eliminuje mutowalna zmienna 'result' calkowicie - kod jest krotszy,
// a kompilator gwarantuje, ze KAZDA galaz faktycznie ustawia wartosc (definite assignment).

// Porownanie: (a) switch na int/enum daje wyczerpanie DLA ZNANEGO Z GORY zbioru wartosci
// (enum) lub wymaga default (int); (b) switch pattern matching + record patterns rozszerza
// to na HIERARCHIE TYPOW sealed, z dekompozycja pol; (c) pattern matching instanceof to
// 'recznie' pisany odpowiednik (b) bez gwarancji wyczerpania kompilatora; (d) sealed classes
// to FUNDAMENT, na ktorym stoi cala gwarancja wyczerpania w (b) - bez sealed, (a) i (b) musza
// miec default.

static String classifyAndDescribe(Object o) {
    String category = (o instanceof String s) ? "tekst"
            : (o instanceof Integer i) ? "liczba"
            : "inne";
    return switch (category) {
        case "tekst" -> "To jest tekst: " + o;
        case "liczba" -> "To jest liczba: " + o;
        default -> "Nieznany typ";
    };
}
System.out.println(classifyAndDescribe("hello"));
System.out.println(classifyAndDescribe(42));
